CREATE TABLE IF NOT EXISTS tally_sync_validation (validation_id TEXT PRIMARY KEY,sync_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,validation_status TEXT NOT NULL,duplicate_flag INTEGER NOT NULL DEFAULT 0,mapping_status TEXT NOT NULL,xml_status TEXT NOT NULL,message TEXT,validated_by TEXT NOT NULL,validated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tally_sync_acknowledgements (acknowledgement_id TEXT PRIMARY KEY,sync_id TEXT NOT NULL,external_reference TEXT,tally_status TEXT NOT NULL,response_message TEXT,received_by TEXT NOT NULL,received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(sync_id,external_reference));
